require_once __DIR__.'/includes/bootstrap.php';require_login();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$_SESSION['user']['id']]);$hash=$s->fetchColumn();if(!password_verify($current,$hash))$err='Current password is incorrect.';elseif(strlen($new)<8)$err='New password must be at least 8 characters.';elseif($new!==$confirm)$err='New passwords do not match.';else{$s=db()->prepare('UPDATE users SET password_hash=? WHERE id=?');$s->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['user']['id']]);$msg='Password changed successfully.';log_action('Password changed');}}$pageTitle='My Account';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><div class="panel" style="max-width:600px"><h2>Change your password</h2><p class="muted">Use a strong password and do not share your login details.</p><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div style="grid-column:1/-1"><label>Current password</label><input type="password" name="current_password" required></div><div><label>New password</label><input type="password" name="new_password" minlength="8" required></div><div><label>Confirm new password</label><input type="password" name="confirm_password" minlength="8" required></div><div class="form-action"><button class="btn primary">Update password</button></div></form></div><?php require 'includes/footer.php';?>
